    "Museums & Galleries": {
        description: "The intersection of fine art, weird history, and local makers.",
        type: "custom",
        items: [
            { header: "The Heavy Hitters" },
            { name: "Speed Art Museum", note: "The oldest and largest art museum in Kentucky. Pay-what-you-can Sundays; check which ones, since the schedule changed in 2026." },
            { name: "Frazier History Museum", note: "The official starting point of the Bourbon Trail." },
            { name: "Muhammad Ali Center", note: "A spectacular, multi-story interactive museum dedicated to the Greatest." },
            { name: "Kentucky Derby Museum", note: "Everything Churchill Downs, right next to the track." },
            { name: "Louisville Slugger Museum & Factory", note: "Look for the 120-foot baseball bat leaning against the building." },
            { name: "Roots 101 African American Museum", note: "Dedicated to telling the story of the African American journey from Africa to Kentucky." },
            { name: "KMAC Museum", note: "Contemporary art focusing on craft and material." },
            { name: "Kentucky Science Center", note: "Great for kids, but the 4-story theater is great for everyone." },
            { name: "Louisville Water Tower", note: "WaterWorks Museum inside the 1860 pumping station, the world's oldest ornamental water tower." },
            { name: "Conrad-Caldwell House", note: "Old Louisville's Richardsonian Romanesque 'castle' on St. James Court. Guided tours." },
            { name: "Filson Historical Society", note: "Kentucky's oldest historical society (1884). Exhibits, lectures, and the Ferguson Mansion." },
            { name: "Locust Grove", note: "18th-century farm and final home of George Rogers Clark. Great living-history days." },
            { name: "Farmington", note: "1816 hemp plantation house built from a Thomas Jefferson design, with honest tours of the enslaved community." },
            { name: "Riverside, the Farnsley-Moremen Landing", note: "1837 farmhouse on a working river landing in the southwest. Free grounds." },
            { name: "SAR Education Center & Museum", note: "Museum Row (809 W Main). American Revolution museum; partial opening July 2026, full opening 2027." },
            { name: "AHOY Children's Museum", note: "Portland. Children's museum on the Portland Museum campus; first phase due late 2026." },
            { header: "Independent Galleries & Niche Museums" },
            { name: "21c Museum Hotel", note: "A free, 24/7 contemporary art museum disguised as a boutique hotel." },
            { name: "American Printing House for the Blind", note: "Braille-book factory tours, plus the new Dot Experience museum opening Oct 30, 2026." },
            { name: "Portland Museum", note: "A deep dive into the river heritage and history of the Portland neighborhood." },
            { name: "Thomas Edison House", note: "He lived in Louisville briefly; this shotgun house explores his time here." },
            { name: "Mellwood Art Center", note: "A massive former slaughterhouse turned into a maze of artist studios." },
            { name: "Louisville Stoneware", note: "Paristown. Watch the pottery get made and paint your own piece." },
            { name: "Revelry Boutique Gallery", note: "NuLu spot championing hyper-local artists." },
            { name: "Garner Narrative", note: "Intimate gallery in NuLu with a focus on contemporary, provocative pieces." },
            { name: "Howard Steamboat Museum", note: "Gorgeous Victorian mansion detailing riverboat history (Jeffersonville)." }
        ]
    },
    "Attractions & Outings": {
        description: "Things to do when you have guests in town, or just need to get out.",
        type: "custom",
        items: [
            { header: "Icons & Green Spaces" },
            { name: "The Belle of Louisville", note: "The oldest operating Mississippi-style steamboat in the world." },
            { name: "Louisville Zoo", note: "134 acres. The Glacier Run and Gorilla Forest are world-class." },
            { name: "Waterfront Botanical Gardens", note: "Built on top of a former landfill, now a stunning oasis overlooking the river." },
            { name: "Cave Hill Cemetery", note: "An incredibly beautiful Victorian garden cemetery. Visit Ali and Colonel Sanders.", free: true },
            { name: "The Big Four Bridge", note: "The pedestrian bridge connecting Louisville to Indiana. Best walked at sunset.", free: true },
            { name: "Churchill Downs", note: "Live racing in the spring and fall meets, not just Derby Day. Grandstand renovated for Derby 150." },
            { name: "Waterfront Park", note: "85 riverfront acres downtown. The West End expansion's first piece, PlayPort, opened in 2025.", free: true },
            { name: "Whiskey Row", note: "The W Main St blocks of 1800s cast-iron and bourbon distilleries. Walk it end to end.", free: true },
            { name: "Louisville Slugger Field", note: "Home of the Bats. Cheap seats, river views, and Thirsty Thursdays." },
            { header: "Entertainment & Oddities" },
            { name: "Louisville Mega Cavern", note: "A massive former limestone quarry. Ziplines, a ropes course, and holiday lights, all underground." },
            { name: "Idlewild Butterfly Farm" },
            { name: "Vernon Lanes", note: "Oldest bowling alley in KY (bowling here since about 1918). Reopened in 2022: great food, historic lanes." },
            { name: "Recbar", note: "Jeffersontown. Massive arcade bar with 130+ vintage cabinets and pinball machines." },
            { name: "Kentucky Kingdom", note: "The amusement and water park at the fairgrounds. Ride the Flying Fox, the new suspended coaster." },
            { name: "Topgolf", note: "Oxmoor. Climate-controlled driving range bays with food and drinks." },
            { name: "GoodBounce Pickleball Yard", note: "Outdoor and covered pickleball with a bar and food." },
            { name: "Iroquois Amphitheater", note: "Outdoor concerts in a hollow of Iroquois Park." }
        ]
    },
