    "Sports, Clubs & Activities": {
        description: "Teams to cheer for, then how to meet people in this town, from mainstream kickball to obscure street games.",
        type: "custom",
        items: [
            { header: "Teams to Watch" },
            { name: "Bellarmine Knights", note: "Knights Hall" },
            { name: "Louisville Bats", note: "Louisville Slugger Field" },
            { name: "Louisville Cardinals Basketball", note: "KFC Yum! Center" },
            { name: "Louisville Cardinals Baseball", note: "Jim Patterson Stadium" },
            { name: "Louisville Cardinals Volleyball", note: "L&N Federal Credit Union Arena. Perennial top-10; national runner-up in 2022 and 2024" },
            { name: "Louisville Cardinals Women's Basketball", note: "KFC Yum! Center" },
            { name: "Louisville Cardinals Football", note: "L&N Stadium" },
            { name: "Louisville Cardinals Hockey", note: "Iceland Sports Complex" },
            { name: "Louisville City FC", note: "Lynn Family Stadium" },
            { name: "Racing Louisville FC", note: "Lynn Family Stadium" },
            { name: "Louisville Kings (UFL)", note: "Lynn Family Stadium. Won the UFL title in their first season (2026)" },
            { name: "Churchill Downs", note: "Spring and fall racing meets, plus Derby Day" },
            { header: "Active & Sports Leagues" },
            { name: "LXC Sports", note: "The massive mainstream option. Kickball, dodgeball, softball, and flag football." },
            { name: "Louisville Hardcourt Bike Polo", note: "Shelby Park. Pickup games with no set schedule; check their socials." },
            { name: "Derby City Run Club", note: "Meets at local breweries for runs. Very social; people usually stay for a pint after." },
            { name: "Louisville Race Club", note: "Free, no-pressure social 5K on the first and third Saturdays of the month." },
            { name: "Iroquois Hill Runners", note: "Long-running club behind many local races." },
            { name: "Louisville Darts", note: "Competitive and casual dart leagues around town." },
            { name: "Louisville APA Poolplayers Association", note: "The local chapter for amateur pool leagues, playing out of various dive bars and halls." },
            { name: "Louisville Roller Derby", note: "Flat-track roller derby (formerly Derby City Roller Girls), 20 seasons strong. Intensity and camaraderie." },
            { name: "Louisville Rowing Club", note: "Learn-to-row classes and crews on the Ohio. Hosts the Derby City Head Race each October." },
            { header: "The DIY & Maker Scene" },
            { name: "LVL1 Hackerspace", note: "A 24/7 community lab for geeks, engineers, and artists. If you want to build a flamethrower or a robot, go here." },
            { name: "Falls City Community Bikeworks", note: "A DIY shop where you learn to fix your own bike using their tools and knowledge." },
            { name: "Louisville Tool Library", note: "Borrow a power drill or a ladder like you borrow a book." },
            { name: "Payne Street Pottery", note: "Classes and open studio time. Pottery is a very 'zen' way to meet consistent faces." },
            { header: "Games & Nerd Culture" },
            { name: "Louisville Board Gamers", note: "A huge, welcoming group that meets at various libraries and game shops (Heroes, Through the Decades)." },
            { name: "Zanzabar Pinball League", note: "Competitive flipping at one of the best arcades in the region." },
            { header: "Nature & Outdoors" },
            { name: "Louisville Hiking Club", note: "A very active group that organizes group hikes in Jefferson Memorial Forest and the Gorge." },
            { name: "Louisville Grotto", note: "The local chapter of the National Speleological Society. For people who like crawling through caves." },
            { name: "Beckham Bird Club", note: "For birdwatchers. They do field trips to Cave Hill and the Falls of the Ohio." },
            { name: "Louisville Grows", note: "Community gardening and tree planting. Great for meeting people who care about the environment." },
            { header: "Movement & Arts" },
            { name: "Derby City Swing", note: "West Coast Swing dance weekend every January, with workshops and social dancing." },
            { name: "Louisville Country Dancers", note: "Contra Dancing at various church halls. Incredibly welcoming to beginners." },
            { name: "Louisville Improvisors", note: "The city's long-running improv troupe, with shows and classes." },
            { name: "Turners Circus", note: "Aerial silks, trapeze, and gymnastics. A very tight-knit 'circus family' vibe." },
            { header: "Combat & Competition" },
            { name: "Louisville Fencing Center", note: "One of the strongest fencing programs in the region. Welcomes absolute beginners and competitive fencers alike." },
            { name: "Louisville TKO Boxing", note: "Youth boxing nonprofit on E Breckinridge St." },
            { name: "Columbia Gym", note: "Where 12-year-old Cassius Clay first learned to box. Now Spalding University's gym." },
            { name: "Louisville Chess Club", note: "Regular events, tournaments, and casual games. One of the more active chess communities in Kentucky." },
            { header: "The Strange & Obscure" },
            { name: "Waverly Hills Sanatorium", note: "The massive, decaying epicenter of Louisville ghost lore. Overnight stays for the brave." },
            { name: "American Printing House for the Blind", note: "Factory tours of a world-class braille publisher in Clifton, plus the new Dot Experience museum (Oct 2026)." },
            { header: "Civic & Professional" },
            { name: "YPAL (Young Professionals Association)", note: "The standard for networking if you are 20-40 and looking for social crossovers." },
            { name: "Neighborhood Associations", note: "Search for your specific 'hood (Clifton, Germantown, etc). Meet your actual neighbors." },
            { name: "Metro Health Harm Reduction", note: "Community health, overdose prevention, and harm reduction resources.", url: "https://louisvilleky.gov/government/health-wellness/harm-reduction" }
        ]
    },
